package com.franco.desco.application.access.service;
import com.franco.desco.application.access.RoleCommands.*; import com.franco.desco.application.access.port.in.RoleUseCase; import com.franco.desco.application.access.port.out.RolePersistencePort; import com.franco.desco.application.shared.*; import com.franco.desco.application.shared.pagination.PageResult; import com.franco.desco.domain.access.RoleModels;
public final class RoleApplicationService implements RoleUseCase { private final RolePersistencePort p; public RoleApplicationService(RolePersistencePort p){this.p=p;}
 public AppResult<PageResult<RoleModels.Summary>> list(ListRoles c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"ROLES_LISTADOS","ROLES_NO_LISTADOS",AppStatus.BAD_REQUEST);} public AppResult<RoleModels.Detail> get(GetRole c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"ROL_OBTENIDO","ROL_NO_DISPONIBLE",AppStatus.NOT_FOUND);} public AppResult<Long> create(CreateRole c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"ROL_CREADO","ROL_NO_CREADO");} public AppResult<Void> update(UpdateRole c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"ROL_ACTUALIZADO","ROL_NO_ACTUALIZADO",AppStatus.BAD_REQUEST);} public AppResult<Void> disable(DisableRole c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.disable(c,i,m),"ROL_DESHABILITADO","ROL_NO_DESHABILITADO",AppStatus.BAD_REQUEST);} public AppResult<Void> updatePermissions(UpdatePermissions c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.updatePermissions(c,i,m),"ROL_PERMISOS_ACTUALIZADOS","ROL_PERMISOS_NO_ACTUALIZADOS",AppStatus.BAD_REQUEST);} }
